CREATE SET TABLE MDP01_META.META_ETL_JOB_PARAMETER ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      parameter_id INTEGER NOT NULL,      etl_job_id INTEGER NOT NULL,      parameter_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      parameter_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      default_value VARCHAR(1000) CHARACTER SET LATIN NOT CASESPECIFIC,      is_required CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      beschreibung VARCHAR(1000) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( parameter_id )UNIQUE INDEX ( etl_job_id ,parameter_name );